{
  "gaps": [
    {
      "concept": "The endometrial functionalis is shed during menstruation; the basalis remains and regenerates the lining.",
      "why_tested": "A histology or curettage stem asks which layer regenerates or why injury to the basalis causes amenorrhea.",
      "yield": "hi"
    },
    {
      "concept": "Estrogen drives the proliferative phase, producing straight tubular glands and mitotic stromal cells.",
      "why_tested": "A biopsy taken before ovulation asks for the phase or dominant hormone.",
      "yield": "hi"
    },
    {
      "concept": "Progesterone drives the secretory phase, producing coiled, sawtooth glands with glycogen-rich secretions and stromal edema.",
      "why_tested": "A biopsy after ovulation asks for the phase or hormone responsible.",
      "yield": "hi"
    },
    {
      "concept": "Corpus luteum regression causes progesterone withdrawal, spiral artery constriction, and shedding of the functionalis.",
      "why_tested": "A menstrual physiology stem asks what initiates bleeding in a cycle without pregnancy.",
      "yield": "hi"
    },
    {
      "concept": "Anovulation prevents corpus luteum formation, leaving estrogen unopposed by luteal progesterone and causing irregular endometrial bleeding.",
      "why_tested": "A patient with irregular cycles and bleeding has proliferative endometrium without secretory change.",
      "yield": "hi"
    },
    {
      "concept": "Endometriotic implants undergo cyclic hemorrhage; biopsy may show hemosiderin-laden macrophages, fibrosis, and adhesions.",
      "why_tested": "A pelvic lesion with old hemorrhage asks for the histologic clue or cause of pain.",
      "yield": "hi"
    },
    {
      "concept": "Endometriosis can impair fertility through pelvic adhesions and distortion of reproductive anatomy.",
      "why_tested": "An infertility stem asks how ectopic implants interfere with conception.",
      "yield": "mid"
    },
    {
      "concept": "Continuous GnRH agonist exposure downregulates pituitary GnRH receptors, reducing LH, FSH, and ovarian estrogen after an initial flare.",
      "why_tested": "An endometriosis drug stem asks why continuous treatment suppresses estrogen despite an initial hormone rise.",
      "yield": "hi"
    },
    {
      "concept": "GnRH agonists and antagonists can cause hypoestrogenic hot flashes and bone loss during endometriosis treatment.",
      "why_tested": "A treated patient develops vasomotor symptoms or declining bone density.",
      "yield": "mid"
    },
    {
      "concept": "Danazol suppresses gonadotropins but causes androgenic adverse effects, including acne, hirsutism, and voice deepening.",
      "why_tested": "An endometriosis medication stem asks which drug explains new androgenic symptoms.",
      "yield": "mid"
    },
    {
      "concept": "Adenomyosis causes diffuse junctional-zone thickening and small myometrial cysts, unlike a sharply circumscribed leiomyoma.",
      "why_tested": "Uterine imaging asks which process explains an ill-defined, diffusely abnormal myometrium.",
      "yield": "mid"
    },
    {
      "concept": "Submucosal leiomyomas distort the endometrial cavity and are especially associated with heavy bleeding and infertility.",
      "why_tested": "An imaging stem asks which fibroid location best explains bleeding or impaired implantation.",
      "yield": "hi"
    },
    {
      "concept": "Leiomyomas usually shrink after menopause as ovarian steroid levels fall.",
      "why_tested": "A postmenopausal enlarging uterine mass asks why an ordinary fibroid is less likely.",
      "yield": "hi"
    },
    {
      "concept": "Leiomyosarcoma often presents as a solitary, rapidly enlarging, heterogeneous uterine mass after menopause.",
      "why_tested": "A mass vignette asks for a clue favoring sarcoma over multiple stable fibroids.",
      "yield": "mid"
    },
    {
      "concept": "Endometrial hyperplasia has crowded, irregular glands with an increased gland-to-stroma ratio but no stromal invasion.",
      "why_tested": "A biopsy asks the histologic basis for hyperplasia or its distinction from carcinoma.",
      "yield": "hi"
    },
    {
      "concept": "Atypical endometrial hyperplasia, also called endometrial intraepithelial neoplasia, is a precursor to endometrioid carcinoma.",
      "why_tested": "A pathology stem asks which premalignant lesion can progress to type I carcinoma.",
      "yield": "hi"
    },
    {
      "concept": "Endometrioid carcinoma forms atypical glands with stromal or myometrial invasion and commonly retains estrogen and progesterone receptors.",
      "why_tested": "A biopsy asks how invasive type I carcinoma differs from atypical hyperplasia.",
      "yield": "hi"
    },
    {
      "concept": "Early menarche, late menopause, and nulliparity increase lifetime estrogen exposure and type I endometrial carcinoma risk.",
      "why_tested": "A risk-factor vignette asks which reproductive history increases endometrial cancer risk.",
      "yield": "hi"
    },
    {
      "concept": "Progestin exposure through pregnancy or combined oral contraceptives lowers endometrial hyperplasia and carcinoma risk.",
      "why_tested": "A prevention or risk comparison asks why progesterone offsets estrogen-driven proliferation.",
      "yield": "mid"
    },
    {
      "concept": "Endometrial atrophy is a common benign cause of postmenopausal bleeding; cancer remains an important differential diagnosis.",
      "why_tested": "A postmenopausal bleeding stem asks for the likely cause or a key look-alike.",
      "yield": "mid"
    },
    {
      "concept": "Endometrial polyps contain irregular glands in fibrous stroma with thick-walled vessels and often cause intermenstrual spotting.",
      "why_tested": "A focal intracavitary lesion or biopsy asks for the diagnosis behind spotting.",
      "yield": "hi"
    },
    {
      "concept": "Asherman syndrome follows basalis injury, preventing endometrial regeneration and causing infertility or recurrent pregnancy loss.",
      "why_tested": "A patient has scant menses and infertility after postpartum curettage.",
      "yield": "hi"
    },
    {
      "concept": "Postpartum endometritis presents with fever, uterine tenderness, and foul lochia; cesarean delivery increases risk.",
      "why_tested": "A febrile postpartum patient has a tender uterus and abnormal lochia.",
      "yield": "hi"
    },
    {
      "concept": "Acute endometritis shows neutrophils; chronic endometritis is distinguished by stromal plasma cells.",
      "why_tested": "An endometrial biopsy asks whether inflammation is acute or chronic.",
      "yield": "mid"
    },
    {
      "concept": "Uterine carcinosarcoma is usually a metaplastic epithelial malignancy with a shared clone across carcinomatous and sarcomatous components.",
      "why_tested": "A mixed uterine tumor stem asks for its cellular origin.",
      "yield": "lo"
    },
    {
      "concept": "The uterus develops from fused paramesonephric ducts; failed septum resorption yields a septate uterus with a normal external fundal contour.",
      "why_tested": "Recurrent pregnancy loss with two endometrial cavities and a smooth fundus asks for the embryologic defect.",
      "yield": "hi"
    },
    {
      "concept": "Failed paramesonephric duct fusion produces a bicornuate uterus with an externally indented fundus; complete failure produces uterus didelphys.",
      "why_tested": "Imaging asks whether a divided uterine cavity reflects failed fusion or failed septum resorption.",
      "yield": "hi"
    }
  ]
}
